# == Helpers ==
def set_black(run):
    run.font.color.rgb = RGBColor(0,0,0)

def set_superscript(run):
    rPr = run._element.get_or_add_rPr()
    for old in rPr.findall(qn('w:vertAlign')):
        rPr.remove(old)
    va = rPr.makeelement(qn('w:vertAlign'), {qn('w:val'): 'superscript'})
    rPr.append(va)

def heading(text, level=1):
    p = doc.add_heading(text, level=level)
    for run in p.runs:
        run.font.name = 'Arial'
        set_black(run)
        run.font.size = Pt([14, 12, 11][level-1])
        rPr = run._element.get_or_add_rPr()
        for old in rPr.findall(qn('w:b')):
            rPr.remove(old)
        b = rPr.makeelement(qn('w:b'), {})
        rPr.append(b)
    p.paragraph_format.space_before = Pt(21)
    p.paragraph_format.space_after = Pt(8)
    return p

def p(text, bold=False, italic=False, size=11):
    para = doc.add_paragraph()
    run = para.add_run(text)
    run.font.name = 'Arial'
    run.font.size = Pt(size)
    set_black(run)
    run.bold = bold
    run.italic = italic
    para.paragraph_format.line_spacing = 1.15
    para.paragraph_format.space_after = Pt(4)
    para.paragraph_format.first_line_indent = Cm(0)
    return para

# == Table helpers ==
def add_table_1(doc):
    auc = DATA['table1_auc']
    ds = DATA['datasets']
    para = doc.add_paragraph()
    run = para.add_run(f"Table 1. Classification AUC (area under the ROC curve) of five metrics on Tabula Sapiens ({DATA['human']['n_ct_analyzed']} of {ds['tabula_sapiens_ct_entries']} cell-type entries analyzed; {DATA['human']['n_pairs_total']:,} pairs).")
    run.bold = True
    run.font.name = 'Arial'
    run.font.size = Pt(11)
    para.paragraph_format.space_before = Pt(21)
    para.paragraph_format.space_after = Pt(8)
    table = doc.add_table(rows=6, cols=2)
    table.style = 'Table Grid'
    hdr = table.rows[0].cells
    hdr[0].text = 'Metric'
    hdr[1].text = 'ROC-AUC'
    data = [
        ('Cosine distance', f"{auc['cosine']:.3f}"),
        ('Raw JS divergence', f"{auc['raw_js']:.3f}"),
        ('Marker Jaccard distance', f"{auc['marker_jaccard']:.3f}"),
        ('Spearman distance', f"{auc['spearman']:.3f}"),
        ('CKI \u03c9', f"{auc['cki_omega']:.3f}"),
    ]
    for i, (metric, auc_val) in enumerate(data):
        table.rows[i+1].cells[0].text = metric
        table.rows[i+1].cells[1].text = auc_val
    doc.add_paragraph().paragraph_format.space_after = Pt(8)

def add_table_2(doc):
    t2 = DATA['table2_data']
    has_sep = any(int(r[3]) < 5 for r in t2) and any(int(r[3]) >= 5 for r in t2)
    n_rows = len(t2) + 1 + (1 if has_sep else 0)
    para = doc.add_paragraph()
    run = para.add_run(f"Table 2. Cross-organ conservation ranking by cell type (Tabula Sapiens, n={DATA['cross_organ_n_total']} same-cell-type cross-organ pairs). Well-sampled cell types (n \u2265 5 cross-organ pairs) are ranked first by mean \u03c9; sparsely sampled cell types (n < 5 pairs; SD shown only where n > 1) are listed below the divider, and their rankings should be interpreted as suggestive only. k_f-only controls for this ranking are reported in Additional file 1: Note 3.16.")
    run.bold = True
    run.font.name = 'Arial'
    run.font.size = Pt(11)
    para.paragraph_format.space_before = Pt(21)
    para.paragraph_format.space_after = Pt(8)
    table = doc.add_table(rows=n_rows, cols=4)
    table.style = 'Table Grid'
    hdr = table.rows[0].cells
    hdr[0].text = 'Cell type'
    hdr[1].text = 'Mean \u03c9'
    hdr[2].text = 'SD'
    hdr[3].text = 'n pairs'
    row_i = 1
    sep_done = False
    for (name, mean_w, sd, n) in t2:
        if has_sep and not sep_done and int(n) < 5:
            cells = table.rows[row_i].cells
            cells[0].text = '\u2014 Sparsely sampled (n < 5 pairs): interpret with caution \u2014'
            for c in cells[1:]:
                c.text = ''
            row_i += 1
            sep_done = True
        cells = table.rows[row_i].cells
        cells[0].text = name
        cells[1].text = mean_w
        cells[2].text = sd
        cells[3].text = n
        row_i += 1
    doc.add_paragraph().paragraph_format.space_after = Pt(8)

