def ref_p_nar(text):
    """Add a NAR-formatted reference paragraph."""
    para = doc.add_paragraph(text)
    para.paragraph_format.line_spacing = 1.15
    para.paragraph_format.space_after = Pt(3)
    for run in para.runs:
        run.font.name = 'Arial'
        run.font.size = Pt(10)
        set_black(run)
    return para

