def ab(label, text):
    para = doc.add_paragraph()
    r1 = para.add_run(label + '. ')
    r1.font.name = 'Arial'; r1.font.size = Pt(11); r1.bold = True; set_black(r1)
    r2 = para.add_run(text)
    r2.font.name = 'Arial'; r2.font.size = Pt(11); set_black(r2)
    para.paragraph_format.line_spacing = 1.15
    para.paragraph_format.space_after = Pt(4)
    return para

ab('Background', 'Standard distance metrics conflate baseline variation with functional adaptation in single-cell genomics. Inspired by the Ka/Ks ratio, CKI (Cell-type Ka/Ks-inspired Index) decomposes divergence into a baseline rate k_n (housekeeping genes) and a functional rate k_f (identity genes); \u03c9 = k_f/k_n quantifies baseline-normalized functional divergence.')
ab('Results', 'In a ground-truth simulation, \u03c9 alone rejected neutral housekeeping-gene drift (false-positive rate 0.00, versus 0.55\u20130.58 for raw JS and cosine) and ranked first for functional-versus-neutral discrimination (AUC = 0.80), at the cost of bounded power and blindness to anchor-located signal; the low false-positive rate is not an anchoring artifact, staying \u2264 0.067 under expression-matched non-housekeeping drift (raw JS and cosine: 0.81\u20131.00). We evaluated CKI on mouse, human, pan-cancer (TCGA; exploratory), and brain single-nucleus datasets. Calibration established an equivalent-population baseline (\u03c9 = 7.70, 95% CI [7.37, 8.02]). CKI \u03c9 correlated negatively with all standard distance metrics (Spearman r = \u22120.36 to \u22120.46), partly a k_n-denominator artifact. Brain analysis indicated a 6.10-fold regional differentiation gradient across 10 non-neuronal classes\u2014an upper bound inflated by class-size imbalance (equal-n downsampling: 1.74 [1.64, 1.84])\u2014predominantly k_n-driven (3.21-fold k_n versus 2.03-fold k_f); under a block-shuffle null, four of ten classes showed significant regional structure (three after FDR correction), but no pair survived correction. Per-pair gene selection inflates k_f (median 1.6-fold) but preserves rankings (\u03c1 \u2248 0.92).')
ab('Conclusions', 'CKI provides an interpretable, baseline-normalized index of cell-state divergence whose rankings are robust to gene-panel choice, with a practical window of ~50\u2013200 cells per donor per condition, and is freely available as an open-source package.')

